package com.turboio.addon;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
public final class LifelogAudioArchiveTest {
 static final String ACCOUNT=repeat('a',64),PEER=repeat('b',64),STREAM=repeat('c',32),CLOCK=repeat('d',32);static int checks;static final LifelogAudioArchive.Guard OK=()->{};
 static String repeat(char c,int n){char[] v=new char[n];Arrays.fill(v,c);return new String(v);}static void yes(boolean b){checks++;if(!b)throw new AssertionError(checks);}
 interface Work{void run()throws Exception;}static void reject(String code,Work w)throws Exception{try{w.run();throw new AssertionError("accepted "+code);}catch(IOException e){yes(e.getMessage().equals(code));}}
 static File dir(File f){return new File(f,"lifelog-audio/"+ACCOUNT+"/"+STREAM);}static File raw(File f){return new File(dir(f),"original.frames");}static File state(File f){return new File(dir(f),"state.json");}
 static File folder(File parent,String name)throws Exception{File f=new File(parent,name);yes(f.mkdir());return f;}
 static LifelogAudioArchive open(File f)throws Exception{return new LifelogAudioArchive(f,ACCOUNT,PEER,1,STREAM,OK);}
 static LifelogAudioArchive grouped(File f)throws Exception{return new LifelogAudioArchive(f,ACCOUNT,PEER,1,STREAM,OK,LifelogAudioArchive.COMMIT_MS);}
 static boolean append(LifelogAudioArchive a,long seq,String text,byte[] bytes,LifelogAudioArchive.Guard guard)throws Exception{return a.append(seq,"A3",text,bytes,1000+seq,seq,CLOCK,guard);}
 static long number(Map<String,Object> m,String k){return ((Number)m.get(k)).longValue();}
 public static void main(String[] args)throws Exception{
  File root=new File(args[0]);if(args.length>1){String mode=args[1];if(mode.equals("crash")){LifelogAudioArchive a=open(root);final int[] calls={0};append(a,2,"raw invalid JSON must survive",new byte[]{9,8,7},()->{if(++calls[0]==3)Runtime.getRuntime().halt(17);});throw new AssertionError("no crash");}if(mode.equals("resume")){try(LifelogAudioArchive a=open(root)){yes(number(a.snapshot(),"count")==2);yes(!append(a,2,"raw invalid JSON must survive",new byte[]{9,8,7},OK));a.seal("process_interrupted",OK);yes(Boolean.FALSE.equals(a.snapshot().get("recording_complete")));}System.out.println("Archive separate process recovery passed");return;}}
  File base=folder(root,"normal");byte[] payload=new byte[481];new Random(8).nextBytes(payload);
  try(LifelogAudioArchive a=open(base)){yes(append(a,1,"{malformed source metadata",payload,OK));yes(!append(a,1,"{malformed source metadata",payload,OK));reject("AUDIO_ARCHIVE_REPLAY_CONFLICT",()->append(a,1,"different",payload,OK));reject("AUDIO_ARCHIVE_SEQUENCE_GAP",()->append(a,3,"{}",payload,OK));Map<String,Object> snap=a.snapshot();yes(number(snap,"count")==1&&Boolean.FALSE.equals(snap.get("source_link_verified")));snap.put("count",100);yes(number(a.snapshot(),"count")==1);reject("AUDIO_ARCHIVE_INPUT_INVALID",()->append(a,2,"{}",new byte[LifelogAudioArchive.MAX_PAYLOAD+1],OK));}
  byte[] retained=Files.readAllBytes(raw(base).toPath());ByteBuffer lengths=ByteBuffer.wrap(retained,8,8);int metaBytes=lengths.getInt(),dataBytes=lengths.getInt();Map<String,Object> originalHeader=WireJson.map(WireJson.read(Arrays.copyOfRange(retained,16,16+metaBytes)));yes("{malformed source metadata".equals(originalHeader.get("message")));yes(dataBytes==payload.length&&Arrays.equals(payload,Arrays.copyOfRange(retained,16+metaBytes,16+metaBytes+dataBytes)));
  File initial=folder(root,"initial");try(LifelogAudioArchive a=open(initial)){}Map<String,Object> initialState=WireJson.map(WireJson.read(Files.readAllBytes(state(initial).toPath())));initialState.put("bytes",0);Files.write(state(initial).toPath(),WireJson.bytes(initialState));try(LifelogAudioArchive a=open(initial)){yes(number(a.snapshot(),"bytes")==8&&number(a.snapshot(),"count")==0);}
  Files.write(state(initial).toPath(),WireJson.bytes(initialState));Files.delete(raw(initial).toPath());try(LifelogAudioArchive a=open(initial)){yes(number(a.snapshot(),"bytes")==8);}
  for(int n:new int[]{0,1,7}){File f=folder(root,"magic-"+n);try(LifelogAudioArchive a=open(f)){}Map<String,Object> m=WireJson.map(WireJson.read(Files.readAllBytes(state(f).toPath())));m.put("bytes",0);Files.write(state(f).toPath(),WireJson.bytes(m));Files.write(raw(f).toPath(),new byte[n]);byte[] saved=Files.readAllBytes(state(f).toPath());reject("AUDIO_ARCHIVE_HEADER_INCOMPLETE",()->open(f));yes(raw(f).length()==n&&Arrays.equals(saved,Files.readAllBytes(state(f).toPath())));}
  File deny=folder(root,"deny");reject("GUARD_STOP",()->new LifelogAudioArchive(deny,ACCOUNT,PEER,1,STREAM,()->{throw new IOException("GUARD_STOP");}));yes(!new File(deny,"lifelog-audio").exists());
  File budget=folder(root,"budget");try(LifelogAudioArchive a=open(budget)){}try(RandomAccessFile sparse=new RandomAccessFile(raw(budget),"rw")){sparse.setLength(LifelogAudioArchive.MAX_BYTES+1);}reject("AUDIO_ARCHIVE_BUDGET",()->open(budget));
  try(LifelogAudioArchive a=open(base)){yes(!append(a,1,"{malformed source metadata",payload,OK));yes(append(a,2,"{\"frameCount\":999}",new byte[0],OK));a.seal("source_ended",OK);byte[] before=Files.readAllBytes(state(base).toPath());a.seal("source_ended",OK);yes(Arrays.equals(before,Files.readAllBytes(state(base).toPath())));reject("AUDIO_ARCHIVE_SEAL_CONFLICT",()->a.seal("disconnected",OK));reject("AUDIO_ARCHIVE_NOT_WRITABLE",()->append(a,3,"{}",payload,OK));}
  try(LifelogAudioArchive a=open(base)){yes(number(a.snapshot(),"count")==2&&"source_ended".equals(a.snapshot().get("sealed")));}
  reject("AUDIO_ARCHIVE_OWNER_OR_STATE_INVALID",()->new LifelogAudioArchive(base,ACCOUNT,PEER,2,STREAM,OK));
  File recover=folder(root,"recover");byte[] old;
  try(LifelogAudioArchive a=open(recover)){append(a,1,"{}",payload,OK);old=Files.readAllBytes(state(recover).toPath());append(a,2,"{}",new byte[]{1,2},OK);}
  Files.write(state(recover).toPath(),old);try(LifelogAudioArchive a=open(recover)){yes(number(a.snapshot(),"count")==2);yes(!append(a,2,"{}",new byte[]{1,2},OK));}
  File unacked=folder(root,"unacked");try(LifelogAudioArchive a=open(unacked)){final int[] calls={0};reject("GUARD_STOP",()->append(a,1,"{}",payload,()->{if(++calls[0]==3)throw new IOException("GUARD_STOP");}));yes(Boolean.TRUE.equals(a.snapshot().get("uncertain")));reject("AUDIO_ARCHIVE_NOT_WRITABLE",()->append(a,1,"{}",payload,OK));}
  try(LifelogAudioArchive a=open(unacked)){yes(!append(a,1,"{}",payload,OK));}
  File guarded=folder(root,"guarded");try(LifelogAudioArchive a=open(guarded)){long size=raw(guarded).length();reject("GUARD_STOP",()->append(a,1,"{}",payload,()->{throw new IOException("GUARD_STOP");}));yes(raw(guarded).length()==size);}
  for(int cut:new int[]{1,7,8,15,60}){File f=folder(root,"tail-"+cut);try(LifelogAudioArchive a=open(f)){append(a,1,"{}",payload,OK);}byte[] prefix=Files.readAllBytes(raw(f).toPath());byte[] extra=new byte[cut];if(cut>=8){ByteBuffer.wrap(extra).putInt(100).putInt(240);}Files.write(raw(f).toPath(),extra,StandardOpenOption.APPEND);byte[] all=Files.readAllBytes(raw(f).toPath()),manifest=Files.readAllBytes(state(f).toPath());try(LifelogAudioArchive a=open(f)){yes(Boolean.TRUE.equals(a.snapshot().get("uncertain")));reject("AUDIO_ARCHIVE_NOT_WRITABLE",()->append(a,2,"{}",payload,OK));reject("AUDIO_ARCHIVE_NOT_SEALABLE",()->a.seal("disconnected",OK));}yes(Arrays.equals(all,Files.readAllBytes(raw(f).toPath()))&&Arrays.equals(manifest,Files.readAllBytes(state(f).toPath())));yes(Arrays.equals(prefix,Arrays.copyOf(all,prefix.length)));}
  File corrupt=folder(root,"corrupt");try(LifelogAudioArchive a=open(corrupt)){append(a,1,"{}",payload,OK);}byte[] changed=Files.readAllBytes(raw(corrupt).toPath());changed[changed.length-1]^=1;Files.write(raw(corrupt).toPath(),changed);byte[] manifest=Files.readAllBytes(state(corrupt).toPath());reject("AUDIO_ARCHIVE_COMMITTED_CORRUPT",()->open(corrupt));yes(Arrays.equals(manifest,Files.readAllBytes(state(corrupt).toPath()))&&Arrays.equals(changed,Files.readAllBytes(raw(corrupt).toPath())));
  File sealTamper=folder(root,"seal-tamper");try(LifelogAudioArchive a=open(sealTamper)){append(a,1,"{}",payload,OK);byte[] x=Files.readAllBytes(raw(sealTamper).toPath());x[x.length-1]^=1;Files.write(raw(sealTamper).toPath(),x);reject("AUDIO_ARCHIVE_COMMITTED_CORRUPT",()->a.seal("source_ended",OK));}
  File links=folder(root,"links"),outside=new File(root,"untouched");Files.write(outside.toPath(),new byte[]{3,4});try(LifelogAudioArchive a=open(links)){Files.createSymbolicLink(new File(dir(links),"state.json.partial").toPath(),outside.toPath());reject("AUDIO_ARCHIVE_PATH_INVALID",()->append(a,1,"{}",payload,OK));}yes(Arrays.equals(Files.readAllBytes(outside.toPath()),new byte[]{3,4}));
  File lock=folder(root,"lock");try(LifelogAudioArchive a=open(lock)){try{open(lock);throw new AssertionError();}catch(java.nio.channels.OverlappingFileLockException expected){checks++;}}
  File unicode=folder(root,"unicode");try(LifelogAudioArchive a=open(unicode)){reject("AUDIO_ARCHIVE_INPUT_INVALID",()->append(a,1,"\ud800",new byte[]{1},OK));yes(append(a,1,"原音🙂\n保留全部",new byte[]{1},OK));}try(LifelogAudioArchive a=open(unicode)){yes(!append(a,1,"原音🙂\n保留全部",new byte[]{1},OK));}
  File controls=folder(root,"controls");try(LifelogAudioArchive a=open(controls)){yes(append(a,1,repeat('\u0001',16384),new byte[]{1},OK));}try(LifelogAudioArchive a=open(controls)){yes(number(a.snapshot(),"count")==1);}
  File process=folder(root,"process");try(LifelogAudioArchive a=open(process)){append(a,1,"{}",new byte[]{1},OK);}
  // Group commit (production window): receipts follow at flush/size/seal; complete unreceipted records recover.
  File group=folder(root,"group");
  try(LifelogAudioArchive a=grouped(group)){yes(a.durable());for(int i=1;i<=3;i++)yes(append(a,i,"{}",payload,OK));yes(!a.durable()&&number(a.snapshot(),"count")==3);yes(number(WireJson.map(WireJson.read(Files.readAllBytes(state(group).toPath()))),"count")==0);yes(!append(a,2,"{}",payload,OK));reject("AUDIO_ARCHIVE_REPLAY_CONFLICT",()->append(a,3,"different",payload,OK));a.flush(OK);yes(a.durable()&&number(WireJson.map(WireJson.read(Files.readAllBytes(state(group).toPath()))),"count")==3);yes(append(a,4,"{}",payload,OK));yes(!a.durable());}
  yes(number(WireJson.map(WireJson.read(Files.readAllBytes(state(group).toPath()))),"count")==3);
  try(LifelogAudioArchive a=grouped(group)){yes(a.durable()&&number(a.snapshot(),"count")==4&&Boolean.FALSE.equals(a.snapshot().get("uncertain")));yes(number(WireJson.map(WireJson.read(Files.readAllBytes(state(group).toPath()))),"count")==4);yes(!append(a,4,"{}",payload,OK));yes(append(a,5,"{}",payload,OK));a.seal("source_ended",OK);yes(a.durable());Map<String,Object> sealedState=WireJson.map(WireJson.read(Files.readAllBytes(state(group).toPath())));yes(number(sealedState,"count")==5&&"source_ended".equals(sealedState.get("sealed")));final int[] seen={0};a.visit(b->seen[0]++,OK);yes(seen[0]==5);}
  File groupSize=folder(root,"group-size");byte[] big=new byte[LifelogAudioArchive.MAX_PAYLOAD];
  try(LifelogAudioArchive a=grouped(groupSize)){for(int i=1;i<=3;i++)append(a,i,"{}",big,OK);yes(!a.durable()&&number(WireJson.map(WireJson.read(Files.readAllBytes(state(groupSize).toPath()))),"count")==0);append(a,4,"{}",big,OK);yes(a.durable()&&number(WireJson.map(WireJson.read(Files.readAllBytes(state(groupSize).toPath()))),"count")==4);}
  File groupTorn=folder(root,"group-torn");long whole;
  try(LifelogAudioArchive a=grouped(groupTorn)){append(a,1,"{}",payload,OK);a.flush(OK);append(a,2,"{}",payload,OK);whole=raw(groupTorn).length();append(a,3,"{}",payload,OK);}
  try(RandomAccessFile cut=new RandomAccessFile(raw(groupTorn),"rw")){cut.setLength(whole+20);}
  try(LifelogAudioArchive a=grouped(groupTorn)){Map<String,Object> snap=a.snapshot();yes(number(snap,"count")==2&&Boolean.TRUE.equals(snap.get("uncertain"))&&"partial_record".equals(snap.get("tail_error")));reject("AUDIO_ARCHIVE_NOT_WRITABLE",()->append(a,3,"{}",payload,OK));reject("AUDIO_ARCHIVE_NOT_WRITABLE",()->a.flush(OK));}
  yes(raw(groupTorn).length()==whole+20&&number(WireJson.map(WireJson.read(Files.readAllBytes(state(groupTorn).toPath()))),"count")==1);
  File groupGuard=folder(root,"group-guard");
  try(LifelogAudioArchive a=grouped(groupGuard)){append(a,1,"{}",payload,OK);reject("GUARD_STOP",()->a.flush(()->{throw new IOException("GUARD_STOP");}));yes(Boolean.TRUE.equals(a.snapshot().get("uncertain")));reject("AUDIO_ARCHIVE_NOT_WRITABLE",()->append(a,2,"{}",payload,OK));}
  try(LifelogAudioArchive a=grouped(groupGuard)){yes(number(a.snapshot(),"count")==1&&!append(a,1,"{}",payload,OK));}
  reject("AUDIO_ARCHIVE_OWNER_INVALID",()->new LifelogAudioArchive(folder(root,"group-window"),ACCOUNT,PEER,1,STREAM,OK,60001));
  System.out.println("Lifelog audio archive: "+checks+" checks passed; synthetic filesystem only");
 }
}
